window.RTR_T=window.RTR_T||{};RTR_T["n1"]={"code": "N-1", "title": "Oftalmologiyaning rivojlanish tarixi. Koʻruv organi anatomiyasi. Koʻzning koʻrish faoliyati", "hours": 2, "minutes": 80, "goal": "Oʻquvchilarda oftalmologiya fanining mazmuni, qisqacha rivojlanish tarixi, koʻruv organining anatomik tuzilishi va koʻzning asosiy koʻrish funksiyalari toʻgʻrisida bilim hamda ularni hamshiralik amaliyotida qoʻllash koʻnikmalarini shakllantirish.", "plan": ["“Oftalmologiya” fani haqida tushuncha va uning tibbiyot fanlari orasidagi oʻrni", "Oftalmologiya fanining rivojlanish tarixi", "Koʻruv organi anatomiyasi", "Koʻruv organining faoliyati (koʻrish funksiyalari)"], "outcomes": ["Oftalmologiya fani haqida tushuncha va uning tibbiyot fanlari orasidagi oʻrnini aytib beradi.", "Oftalmologiya fanining qisqacha rivojlanish tarixini, unga hissa qoʻshgan olimlarni sanab beradi.", "Koʻzning tuzilishi, pardalari, ichki muhitlari va yordamchi apparatini aytib, rasmda koʻrsatib beradi.", "Koʻzning koʻrish faoliyati: markaziy, periferik, rang, yorugʻlik va binokulyar koʻrishni tushuntirib beradi."], "keywords": ["oftalmologiya", "koʻruv analizatori", "koʻz olmasi", "shox parda", "sklera", "tomirli parda", "toʻr parda", "gavhar", "shishasimon tana", "koʻrish oʻtkirligi", "koʻruv maydoni", "rang koʻrish", "binokulyar koʻrish"], "methods": [{"name": "Tezkor savol-javob (blits-soʻrov)", "stage": "Tayanch bilimlarni faollashtirish (5 daqiqa)", "goal": "Anatomiya va fiziologiya fanlaridan olingan bilimlarni yodga tushirish, yangi mavzuga koʻprik yaratish.", "steps": ["Oʻqituvchi qisqa, aniq javob talab qiladigan savollarni ketma-ket beradi.", "Oʻquvchilar navbat bilan 10–15 soniyada javob beradi.", "Notoʻgʻri javoblar darhol boshqa oʻquvchi tomonidan toʻgʻrilanadi."], "task": ["“Oftalmos” soʻzi nimani anglatadi?", "Analizator necha qismdan iborat?", "Koʻruv organining asosiy va yordamchi qismlarini ayting.", "Koʻruv markazi bosh miyaning qaysi boʻlagida joylashgan?"]}, {"name": "Taqdimot va vizual koʻrgazmali bayon (mini-maʼruza)", "stage": "Yangi materialni bayon qilish (35 daqiqa)", "goal": "Mavzuning nazariy holatlarini slaydlar, infografika va animatsiya yordamida tushunarli yetkazish.", "steps": ["Reja asosida har bir savol slaydlar orqali sharhlanadi.", "Koʻz olmasi kesimi rasmida har bir parda va muhit koʻrsatgich bilan koʻrsatiladi.", "“Nur yoʻli” animatsiyasi orqali koʻrish jarayoni namoyish etiladi.", "Oʻquvchilar asosiy tushunchalarni daftarga yozib boradi."], "task": ["Slaydlar: RTR → “Taqdimot” boʻlimi", "Animatsiya: RTR → “Media” boʻlimi"]}, {"name": "Klaster (tarmoqlash)", "stage": "Yangi materialni tizimlashtirish (7 daqiqa)", "goal": "Koʻruv organining tuzilmalari oʻrtasidagi bogʻliqlikni grafik koʻrinishda ifodalash.", "steps": ["Doska markaziga “KOʻRUV ORGANI” soʻzi yoziladi.", "Oʻquvchilar undan tarmoqlar chiqaradi: koʻz olmasi → pardalar → qismlari; ichki muhitlar; yordamchi apparat.", "Har bir tarmoq oxiriga tuzilmaning vazifasi yoziladi.", "Tayyor klaster maʼruzadagi jadval bilan solishtiriladi."], "task": ["Koʻz olmasining uch pardasi va ularning qismlari boʻyicha klaster tuzing."]}, {"name": "“Galereya boʻylab sayohat”", "stage": "Mustahkamlash (15 daqiqa)", "goal": "Kichik guruhlarda ishlab, bir-birining javoblarini baholash va toʻldirish orqali bilimlarni mustahkamlash.", "steps": ["Guruh 3 ta kichik guruhga boʻlinadi (“Ibn Sino”, “Gelmgols”, “Filatov”).", "Har bir guruh flipchart varagʻida oʻz savoliga javob yozadi (5 daqiqa).", "Varaqlar soat mili boʻyicha almashtiriladi, har bir guruh boshqa guruh javobini boshqa rangli marker bilan toʻldiradi.", "Varaq egasiga qaytgach, guruh sardori yakuniy javobni taqdim etadi, oʻqituvchi xulosa qiladi."], "task": ["1-guruh: Oftalmologiya rivojiga hissa qoʻshgan olimlar va ularning kashfiyotlari (vaqt chizigʻi).", "2-guruh: Koʻz olmasining pardalari va ichki muhitlari (sxema chizib, belgilash).", "3-guruh: Koʻzning 5 ta koʻrish funksiyasi va ularni tekshirish usullari (jadval)."]}, {"name": "Insert (belgilar bilan oʻqish)", "stage": "Mustaqil oʻqish (uyga vazifa)", "goal": "Matnni tanqidiy va diqqat bilan oʻqish koʻnikmasini rivojlantirish.", "steps": ["Oʻquvchi maʼruza matnini oʻqib, satr chetiga belgi qoʻyadi: “V” – bilardim; “+” – yangi maʼlumot; “–” – boshqacha oʻylardim; “?” – tushunarsiz.", "Belgilar boʻyicha jadval toʻldiriladi.", "Keyingi darsda “?” belgili savollar muhokama qilinadi."], "task": ["“Koʻruv organining faoliyati” boʻlimini Insert usulida oʻqing va jadval tuzing."]}, {"name": "Test va interaktiv mashqlar", "stage": "Nazorat va baholash (10 daqiqa)", "goal": "Mavzuning oʻzlashtirilishini xolis baholash.", "steps": ["Oʻquvchilar RTRdagi 30 savollik testni kompyuter yoki smartfonda yechadi.", "Natija avtomatik hisoblanadi, xatolar tahlil qilinadi.", "“Atama – taʼrif” moslashtirish mashqi bajariladi."], "task": ["RTR → “Nazorat” boʻlimi"]}], "review": ["Oftalmologiya qanday fan va uning asosiy vazifalari nimalardan iborat?", "Nima uchun koʻrishning pasayishi ijtimoiy muammo hisoblanadi?", "Qaysi umumiy kasalliklar koʻzda oʻz aksini topadi? Misollar keltiring.", "Abu Ali ibn Sino oftalmologiya rivojiga qanday hissa qoʻshgan?", "Gelmgols, Snellen va Gullstrandning kashfiyotlarini ayting.", "Koʻruv analizatori qanday qismlardan iborat?", "Koʻz olmasining uch pardasini va ularning qismlarini sanab bering.", "Shox pardaning xususiyatlarini ayting. Nima uchun unga tushgan yot jism kuchli ogʻriq beradi?", "Qorachiqning vazifasi nima va uni qaysi muskullar boshqaradi?", "Kiprikli tananing qanday vazifalari bor?", "Tayoqchalar va kolbachalarning farqi nimada?", "Nima uchun koʻruv nervi diski “koʻr dogʻ” deb ataladi?", "Koʻzning ichki tiniq muhitlarini ayting. Koʻz ichi bosimining normasi qancha?", "Koʻz yoshi qanday yoʻl bilan burun boʻshligʻiga tushadi?", "Koʻz olmasini harakatlantiruvchi muskullarni va ularni innervatsiya qiluvchi nervlarni ayting.", "Koʻzning 5 ta asosiy koʻrish funksiyasini sanab bering.", "Koʻrish oʻtkirligi qanday tekshiriladi va hujjatga qanday yoziladi?", "Gemeralopiya nima va uning oldini olish uchun qanday maslahat beriladi?"], "tasks": [{"title": "1-topshiriq. Koʻz olmasi sxemasini belgilash", "text": "RTRning Quyidagi raqamlangan koʻz olmasi kesimi rasmini daftaringizga chizing va 1–16 raqamlar bilan belgilangan tuzilmalarning nomini yozing. Har bir tuzilmaning bitta asosiy vazifasini koʻrsating.", "check": "Barcha 16 tuzilma toʻgʻri nomlangan va vazifasi koʻrsatilgan boʻlsa – “aʼlo”.", "img": "02_koz_kesimi_raqamli.png", "answers": ["Shox parda", "Limb", "Oldingi kamera", "Rangdor parda", "Qorachiq", "Kiprikli tana", "Sinn boylamlari", "Gavhar", "Sklera (oqsil parda)", "Xususiy tomirli parda", "Toʻr parda", "Shishasimon tana", "Sariq dogʻ", "Koʻruv nervi diski", "Koʻruv nervi", "Toʻgʻri muskul"]}, {"title": "2-topshiriq. Koʻrish oʻtkirligini aniqlash (rolli oʻyin)", "text": "Juftlikda ishlang: biri “hamshira”, biri “bemor”. Sivtsev–Golovin jadvali yordamida 5 m masofadan har bir koʻzning koʻrish oʻtkirligini tekshiring va natijani tibbiy hujjat shaklida yozing (Visus OD = …; Visus OS = …). Soʻng rollarni almashtiring.", "check": "Tekshiruv algoritmi (masofa, yoritish, koʻzni bosmasdan yopish, har bir belgiga 2–3 soniya, yozuv shakli) toʻliq bajarilishi baholanadi."}, {"title": "3-topshiriq. Vaziyatli masala", "text": "Poliklinikaga 45 yoshli haydovchi murojaat qildi. U soʻnggi oylarda kechqurun mashina haydaganda yoʻlni yomon koʻrayotganini, kunduzi esa koʻrishi yaxshi ekanini aytadi. Ovqatlanishi bir xil, sabzavot va sut mahsulotlarini kam isteʼmol qiladi. Savollar: 1) Bemorda qaysi koʻrish funksiyasi buzilgan? 2) Bu holat qanday ataladi? 3) Qanday sabab boʻlishi mumkin? 4) Hamshira qanday maslahatlar beradi?", "check": "Javob: qorongʻilik adaptatsiyasi (yorugʻlik sezish) buzilgan; gemeralopiya (“tovuq koʻrlik”); ehtimoliy sabab – A vitamini yetishmovchiligi; maslahat – oftalmologga yoʻllash, A vitaminiga boy mahsulotlar (sabzi, jigar, sariyogʻ, tuxum sarigʻi), kechasi haydashni vaqtincha cheklash."}, {"title": "4-topshiriq. Vaziyatli masala", "text": "Hamshira maktabda profilaktik koʻrik oʻtkazmoqda. 9 yoshli oʻgʻil bola Sivtsev jadvalining birinchi qatorini ham 5 m dan oʻqiy olmadi, lekin 3 m ga yaqinlashganda oʻqidi. Savollar: 1) Bolaning koʻrish oʻtkirligini Snellen formulasi boʻyicha hisoblang. 2) Natija qanday yoziladi? 3) Hamshiraning keyingi harakatlari qanday?", "check": "Javob: V = d/D = 3/50 = 0,06; Visus = 0,06; ota-onaga xabar berish va oftalmolog koʻrigiga yoʻllash, tibbiy kartaga qayd etish."}, {"title": "5-topshiriq. Mashq: Snellen formulasi", "text": "Bemor jadvalning birinchi qatorini (D = 50 m) quyidagi masofalardan oʻqidi. Koʻrish oʻtkirligini hisoblang: a) 4 m; b) 1 m; c) 0,5 m; d) 2,5 m.", "check": "Javoblar: a) 0,08; b) 0,02; c) 0,01; d) 0,05."}], "matching": [["Kolbachalar", "Kunduzgi va rangli koʻrishni taʼminlovchi fotoretseptorlar"], ["Tayoqchalar", "Gʻira-shira va qorongʻida koʻrishni taʼminlovchi fotoretseptorlar"], ["Qorachiq", "Rangdor parda markazidagi, yorugʻlik miqdorini boshqaruvchi teshik"], ["Sklera", "Fibroz pardaning oq, noshaffof qismi"], ["Gavhar", "Ikki tomoni qavariq, tiniq, elastik linza"], ["Limb", "Shox pardaning skleraga oʻtish joyi"], ["Visus", "Koʻrish oʻtkirligi"], ["Fuziya", "Ikki koʻzdagi tasvirlarning yagona tasvirga qoʻshilishi"]], "structure": [["Tashkiliy qism", "5 daq.", "Salomlashish, davomat"], ["Tayanch bilimlarni faollashtirish", "5 daq.", "Tezkor savol-javob"], ["Yangi mavzu bayoni", "35 daq.", "Taqdimot, video, animatsiya, plakat"], ["Tizimlashtirish", "7 daq.", "Klaster"], ["Mustahkamlash", "15 daq.", "“Galereya boʻylab sayohat”, kichik guruhlar"], ["Nazorat va baholash", "10 daq.", "Test, moslashtirish mashqi"], ["Yakun, uyga vazifa", "3 daq.", "Insert usulida oʻqish"]], "literature": ["Yuldasheva F. S., Yusupova M. S., Aripova S. M. Koʻz kasalliklari. – Toshkent: Choʻlpon nomidagi NMIU, 2007.", "Poʻlatova Sh. A., Aripova G. S., Mirzajonova G. X. va boshq. Kattalarda hamshiralik parvarishi. II qism. – Toshkent, 2012.", "Bikbov M. M. va boshq. Oftalmologiya: darslik (rus tilida). – Moskva: GEOTAR-Media, 2019.", "World Health Organization. World report on vision. – Geneva: WHO, 2019.", "Abu Ali ibn Sino. Tib qonunlari. III kitob. – Toshkent: Fan, 1993 (oʻzbek tilidagi nashr)."], "handouts": [{"title": "Tarqatma material: koʻz pardalari", "rows": [["Parda", "Qismlari", "Asosiy vazifasi"], ["Tashqi (fibroz)", "Shox parda (1/6), sklera (5/6)", "Shakl berish, himoya; shox parda – nur oʻtkazish va sindirish"], ["Oʻrta (tomirli)", "Rangdor parda, kiprikli tana, xususiy tomirli parda", "Oziqlantirish, yorugʻlikni boshqarish, koʻz ichi suyuqligi, akkomodatsiya"], ["Ichki (toʻr)", "Optik qism, koʻrmaydigan qism", "Yorugʻlikni qabul qilib, nerv impulsiga aylantirish"]]}], "algorithms": [{"title": "Koʻrish oʻtkirligini aniqlash", "tools": "Sivtsev–Golovin jadvali, Rot apparati, koʻrsatgich, toʻsiq", "steps": ["Bemorga tekshiruv maqsadini tushuntiring va uni jadvaldan 5 m masofaga oʻtqazing.", "Rot apparatini yoqing: jadval bir tekis yoritilgan boʻlishi kerak.", "Chap koʻzni toʻsiq bilan bosmasdan yoping va avval oʻng koʻzni tekshiring.", "Koʻrsatgich bilan harflarni yuqori qatordan boshlab koʻrsating, har bir belgiga 2–3 soniya bering.", "Bemor xatosiz oʻqigan eng pastki qatorni aniqlang (0,3–0,6 qatorlarda bitta, 0,7–1,0 qatorlarda ikkita xatoga yoʻl qoʻyiladi).", "Xuddi shu tartibda chap koʻzni tekshiring.", "Natijani yozing: Visus OD = …; Visus OS = ….", "Toʻsiq va koʻrsatgichni dezinfeksiya qiling."]}], "interactive": ["ray", "pupil", "blind", "snellen"], "type": "Nazariy", "lecture": "<section class=\"lec-sec\" id=\"lec-1\"><h2>1. “Oftalmologiya” fani haqida tushuncha va uning tibbiyot fanlari orasidagi oʻrni</h2><p>Oftalmologiya (yunoncha ophthalmos – koʻz, logos – taʼlimot, fan) – koʻruv aʼzosining tuzilishi, fiziologiyasi, kasalliklarining kelib chiqish sabablari, rivojlanishi, belgilari, tashxisi, davolash va oldini olish usullarini oʻrganadigan klinik tibbiyot fanidir. Oftalmologiyani qisqacha “koʻz kasalliklari toʻgʻrisidagi fan” deb ham atashadi. Koʻz kasalliklari bilan shugʻullanuvchi shifokor oftalmolog (okulist), koʻz boʻlimi yoki kabinetida ishlovchi hamshira esa oftalmologik hamshira deyiladi.</p><p>Inson tashqi muhit toʻgʻrisidagi maʼlumotlarning 80–90 foizini koʻruv aʼzosi orqali qabul qiladi. Koʻrish qobiliyati odamning oʻqishi, kasb egallashi, mehnat qilishi, transport boshqarishi va jamiyatdagi faol hayoti uchun zarur shartdir. Shu sababli koʻrishning pasayishi yoki yoʻqolishi nafaqat tibbiy, balki katta ijtimoiy muammo hisoblanadi. Jahon sogʻliqni saqlash tashkilotining maʼlumotlariga koʻra, dunyoda kamida 2,2 milliard kishida koʻrish buzilishi mavjud boʻlib, ularning deyarli yarmida bu holatning oldini olish yoki uni oʻz vaqtida davolash mumkin edi. Koʻrlik va zaif koʻrishning asosiy sabablari – tuzatilmagan refraksiya anomaliyalari (miopiya, gipermetropiya, astigmatizm), katarakta, glaukoma, qandli diabet asoratlari (diabetik retinopatiya) va yoshga bogʻliq makula degeneratsiyasidir.</p><h3>Oftalmologiyaning vazifalari</h3><ul><li>koʻruv aʼzosining normal tuzilishi va faoliyatini oʻrganish;</li><li>koʻz kasalliklarining sabablari va rivojlanish mexanizmlarini aniqlash;</li><li>koʻzni tekshirishning zamonaviy usullarini ishlab chiqish va amaliyotga joriy etish;</li><li>koʻz kasalliklarini konservativ (dori-darmon, fizioterapiya) va jarrohlik (mikroxirurgiya, lazer) usullari bilan davolash;</li><li>koʻrlik va zaif koʻrishning oldini olish, aholi oʻrtasida profilaktik koʻriklar oʻtkazish;</li><li>koʻzi ojiz va zaif koʻruvchi shaxslarni reabilitatsiya qilish, mehnat qobiliyatini ekspertiza qilish.</li></ul><h3>Oftalmologiyaning boʻlimlari</h3><p>Hozirgi zamon oftalmologiyasi bir nechta mustaqil yoʻnalishlarga boʻlinadi: bolalar oftalmologiyasi, oftalmoxirurgiya (koʻz mikroxirurgiyasi), lazer oftalmologiyasi, refraksion jarrohlik, glaukomatologiya, kontaktologiya (kontakt linzalar tanlash), neyrooftalmologiya, oftalmoonkologiya, koʻz travmatologiyasi va oftalmologik ekspertiza. Har bir yoʻnalishda hamshira shifokorning yaqin yordamchisi sifatida ishtirok etadi.</p><h3>Oftalmologiyaning boshqa fanlar bilan bogʻliqligi</h3><p>Koʻz organizmning ajralmas qismi boʻlgani uchun koʻplab umumiy kasalliklar koʻzda oʻz aksini topadi. Masalan, gipertoniya kasalligida koʻz tubi tomirlari torayadi va toʻr pardada qon quyilishlar paydo boʻladi; qandli diabetda diabetik retinopatiya va katarakta rivojlanadi; buyrak kasalliklari, ateroskleroz, revmatizm, sil, toksoplazmoz, bosh miya oʻsmalari va jarohatlari ham koʻz tubida oʻziga xos oʻzgarishlar beradi. Shu sababli oftalmolog koʻpincha terapevt, nevropatolog, endokrinolog, pediatr, otorinolaringolog, stomatolog va neyroxirurg bilan hamkorlikda ishlaydi. Koʻz tubini tekshirish (oftalmoskopiya) koʻplab umumiy kasalliklarning tashxisi va kechishini baholashda muhim ahamiyatga ega.</p><p>Oftalmologiya fani normal anatomiya, normal fiziologiya, gistologiya, fizika (optika), lotin tili va tibbiy terminologiya, farmakologiya, mikrobiologiya, terapiya, pediatriya, jarrohlik va hamshiralik ishi asoslari fanlari bilan uzviy bogʻliq. Masalan, koʻzning nur sindirish tizimini tushunish uchun fizikadan optika qonunlarini, koʻz kasalliklarida qoʻllaniladigan tomchi dorilarni toʻgʻri tayyorlash va tomizish uchun esa farmakologiya va hamshiralik manipulyatsiyalarini bilish talab etiladi.</p><h3>Aholiga oftalmologik yordamni tashkil etish</h3><p>Respublikamizda aholiga koʻz boʻyicha tibbiy yordam bosqichma-bosqich koʻrsatiladi. Birlamchi boʻgʻinda – oilaviy poliklinika va oilaviy shifokor punktlarida koʻrish oʻtkirligi aniqlanadi, koʻz ichi bosimi oʻlchanadi, oddiy yalligʻlanish kasalliklari davolanadi, koʻzga tushgan yot jismlar olinadi va bemorlar zarur hollarda ixtisoslashgan muassasaga yoʻllanadi. Ikkinchi bosqichda tuman (shahar) tibbiyot birlashmalarining koʻz kabinetlari va boʻlimlari, uchinchi bosqichda esa viloyat koʻz kasalliklari shifoxonalari hamda respublika ixtisoslashtirilgan markazlari faoliyat koʻrsatadi. Maktab va maktabgacha taʼlim muassasalarida bolalar har yili koʻrikdan oʻtkaziladi, 40 yoshdan oshgan barcha shaxslarda glaukomani erta aniqlash maqsadida koʻz ichi bosimini oʻlchash tavsiya etiladi. Qandli diabet bilan ogʻrigan bemorlar yiliga kamida bir marta koʻz tubi tekshiruvidan oʻtishi lozim. Bu profilaktik tadbirlarni tashkil etish va oʻtkazishda hamshiraning hissasi juda katta.</p><h3>Oftalmologiyada hamshiraning oʻrni</h3><p>Umumiy amaliyot hamshirasi poliklinika, oilaviy shifokor punkti, koʻz kabineti va statsionarning koʻz boʻlimida ishlaydi. Uning asosiy vazifalari quyidagilardan iborat: bemorlarni qabul qilish va tekshiruvga tayyorlash; koʻrish oʻtkirligi, rang koʻrish va koʻz ichi bosimini aniqlashda ishtirok etish; shifokor tayinlagan muolajalarni bajarish (konʼyunktiva boʻshligʻiga tomchi dori tomizish, malham qoʻyish, koʻzni yuvish, bogʻlam qoʻyish); operatsiyadan oldin va keyin bemorni parvarish qilish; koʻzga yot jism tushganda, kuyish va jarohatlarda birinchi yordam koʻrsatish; aholi oʻrtasida koʻz gigiyenasi va koʻrlikning oldini olish boʻyicha sanitariya-oqartuv ishlarini olib borish. Hamshira aseptika va antiseptika qoidalariga qatʼiy rioya qilishi shart, chunki koʻz infeksiyalari (masalan, adenovirusli konʼyunktivit) asboblar va qoʻl orqali oson yuqadi.</p><p>Xulosa qilib aytganda, oftalmologiya klinik tibbiyotning mustaqil, ijtimoiy ahamiyati juda yuqori boʻlgan sohasi boʻlib, uning yutuqlari koʻp jihatdan malakali oʻrta tibbiyot xodimlarining – hamshiralarning bilimi va mahoratiga bogʻliqdir.</p></section><section class=\"lec-sec\" id=\"lec-2\"><h2>2. Oftalmologiya fanining rivojlanish tarixi</h2><p>Koʻz kasalliklari haqidagi dastlabki maʼlumotlar eng qadimgi yozma manbalarda uchraydi. Oftalmologiya tarixini shartli ravishda quyidagi davrlarga boʻlish mumkin: qadimgi dunyo davri, Sharq (oʻrta asrlar) tabobati davri, Yevropa Uygʻonish davri va yangi davr, hozirgi zamon oftalmologiyasi.</p><h3>Qadimgi dunyo davri</h3><figure><img src=\"mavzular/n1/didaktik/07_tarix_vaqt_chizigi.png\" alt=\"Oftalmologiya rivojining asosiy bosqichlari\" loading=\"lazy\" data-zoom><figcaption>Oftalmologiya rivojining asosiy bosqichlari</figcaption></figure><p>Qadimgi Misrda miloddan avvalgi XVI asrga oid Ebers papirusida koʻz kasalliklari va ularni davolash uchun ishlatilgan koʻplab retseptlar keltirilgan. Bobilda podsho Hammurapi qonunlarida (miloddan avvalgi XVIII asr) koʻz operatsiyasi muvaffaqiyatli oʻtsa tabibga toʻlanadigan haq va muvaffaqiyatsiz boʻlsa unga beriladigan jazo belgilangan. Qadimgi Hindistonda tabib Sushruta katarakta (koʻz gavharining xiralashishi)ni gavharni koʻz ichiga tushirib yuborish usuli bilan operatsiya qilgan va 70 dan ortiq koʻz kasalligini tasvirlagan.</p><p>Qadimgi Yunonistonda Gippokrat koʻz kasalliklarining bir qancha turlarini (konʼyunktivit, trixiaz, katarakta) tasvirlagan. Rimlik olim Aul Korneliy Sels (I asr) katarakta operatsiyasini batafsil bayon qilgan, Galen (II asr) esa koʻz anatomiyasi va koʻruv nervi haqida muhim maʼlumotlar qoldirgan. Ammo bu davrda koʻzning nur sindirish vazifasi notoʻgʻri tushunilgan: tasvirni koʻz gavhari qabul qiladi, deb hisoblangan.</p><h3>Sharq tabobati davri (IX–XIII asrlar)</h3><p>Oʻrta asrlarda oftalmologiya Sharq mamlakatlarida, jumladan, Markaziy Osiyoda yuqori darajada rivojlandi. Bu davrda koʻz tabiblari “kahhol” deb atalgan. Hunayn ibn Ishoq (IX asr) “Koʻz haqida oʻn maqola” asarini yozdi – bu oftalmologiyaga oid eng qadimgi tizimli darsliklardan biri hisoblanadi. Ali ibn Iso al-Kahhol (X–XI asrlar) 130 ga yaqin koʻz kasalligini tasvirlagan “Koʻz tabiblari uchun eslatma” kitobini yaratdi. Ammor al-Mavsiliy kataraktani ichi boʻsh ignasimon asbob yordamida soʻrib olish usulini taklif qildi. Ibn al-Haysam (Alhazen) “Optika kitobi”da yorugʻlik koʻzga tashqaridan tushishini va koʻrish jarayonini ilmiy asosda tushuntirdi.</p><p>Buyuk vatandoshimiz Abu Ali ibn Sino (980–1037) “Tib qonunlari” asarining uchinchi kitobida koʻzning anatomiyasi, fiziologiyasi va kasalliklariga keng oʻrin ajratgan. U koʻzning olti tashqi muskulini, koʻruv nervi va uning kesishmasini tasvirlagan, koʻz kasalliklarini davolash uchun koʻplab dori-darmon va jarrohlik usullarini bayon qilgan, koʻz gigiyenasiga katta eʼtibor bergan. Ibn Sino traxoma, katarakta, qovoq kasalliklari va “tungi koʻrlik” haqida qimmatli maʼlumotlar qoldirgan. Uning asarlari lotin tiliga tarjima qilinib, bir necha asr davomida Yevropa universitetlarida asosiy darslik boʻlib xizmat qilgan.</p><h3>Yevropa Uygʻonish davri va yangi davr (XVI–XIX asrlar)</h3><p>1604-yilda nemis olimi Iogann Kepler tasvir toʻr pardada hosil boʻlishini isbotladi, gavhar esa nur sindiruvchi linza vazifasini bajarishini koʻrsatdi. 1748-yilda fransuz jarrohi Jak Daviel kataraktani koʻzdan chiqarib olish (ekstraksiya) operatsiyasini birinchi boʻlib amalga oshirdi. XIX asrda oftalmologiya mustaqil fan sifatida shakllandi: 1851-yilda German Gelmgols koʻz koʻzgusi – oftalmoskopni ixtiro qildi va koʻz tubini tirik odamda koʻrish imkoniyati paydo boʻldi. Gollandiyalik olim Frans Donders koʻzning refraksiyasi va akkomodatsiyasi haqidagi taʼlimotni yaratdi, German Snellen esa 1862-yilda koʻrish oʻtkirligini aniqlash jadvalini taklif qildi. Albrext fon Grefe glaukomani jarrohlik yoʻli bilan davolash (iridektomiya) usulini ishlab chiqdi. 1911-yilda shved olimi Allvar Gullstrand koʻzning optik tizimini oʻrgangani uchun Nobel mukofotiga sazovor boʻldi; u yorituvchi tirqishli lampa – biomikroskopni ham ixtiro qilgan.</p><h3>XX asr va hozirgi zamon oftalmologiyasi</h3><p>XX asrda oftalmologiya jadal rivojlandi. Akademik V. P. Filatov shox pardani koʻchirib oʻtkazish (keratoplastika) usulini takomillashtirdi va toʻqima terapiyasi taʼlimotini yaratdi. Akademik S. N. Fyodorov koʻz mikroxirurgiyasi rivojiga katta hissa qoʻshib, sunʼiy gavhar (intraokulyar linza) qoʻyish va miopiyani jarrohlik yoʻli bilan tuzatish usullarini keng joriy etdi. XX asrning ikkinchi yarmida lazer texnologiyalari, ultratovush tekshiruvi, kompyuter perimetriyasi, optik kogerent tomografiya (OKT) kabi zamonaviy tashxis usullari amaliyotga kirdi.</p><p>Oʻzbekistonda oftalmologiyaning ilmiy asosda rivojlanishi XX asr boshlarida Toshkentda tibbiyot fakulteti va koʻz kasalliklari kafedrasi tashkil etilishi bilan boshlandi. Oʻsha davrda aholi orasida keng tarqalgan traxoma kasalligiga qarshi maxsus traxoma punktlari va dispanserlar tarmogʻi tuzildi, natijada traxoma ommaviy kasallik sifatida tugatildi. Hozirgi kunda respublikamizda Respublika ixtisoslashtirilgan koʻz mikroxirurgiyasi ilmiy-amaliy tibbiyot markazi va uning hududiy filiallari, viloyat koʻz kasalliklari shifoxonalari faoliyat koʻrsatmoqda. Kataraktani fakoemulsifikatsiya usulida olib tashlash, glaukoma va toʻr pardaning lazer bilan davolash, refraksion lazer operatsiyalari muvaffaqiyatli bajarilmoqda.</p><p>Oftalmologiya tarixini bilish hamshiraga bugungi zamonaviy tekshirish va davolash usullarining kelib chiqishini tushunishga, buyuk ajdodlarimiz merosi bilan faxrlanishga va kasbiga masʼuliyat bilan yondashishga yordam beradi.</p><div class=\"tbl\"><table><thead><tr><th>Davr / sana</th><th>Olim yoki manba</th><th>Hissasi</th></tr></thead><tbody><tr><td>Mil. avv. XVI asr</td><td>Ebers papirusi (Misr)</td><td>Koʻz kasalliklarini davolash retseptlari</td></tr><tr><td>Mil. avv. VI asr (taxm.)</td><td>Sushruta (Hindiston)</td><td>Katarakta operatsiyasi, 70 dan ortiq koʻz kasalligi tasviri</td></tr><tr><td>IX asr</td><td>Hunayn ibn Ishoq</td><td>“Koʻz haqida oʻn maqola” darsligi</td></tr><tr><td>X–XI asrlar</td><td>Abu Ali ibn Sino</td><td>“Tib qonunlari”ning 3-kitobida koʻz anatomiyasi va kasalliklari</td></tr><tr><td>1604-yil</td><td>I. Kepler</td><td>Tasvir toʻr pardada hosil boʻlishini isbotladi</td></tr><tr><td>1748-yil</td><td>J. Daviel</td><td>Katarakta ekstraksiyasi operatsiyasi</td></tr><tr><td>1851-yil</td><td>G. Gelmgols</td><td>Oftalmoskopni ixtiro qildi</td></tr><tr><td>1862-yil</td><td>G. Snellen</td><td>Koʻrish oʻtkirligini aniqlash jadvali</td></tr><tr><td>1911-yil</td><td>A. Gullstrand</td><td>Koʻz optikasi, tirqishli lampa; Nobel mukofoti</td></tr><tr><td>XX asr</td><td>V. P. Filatov, S. N. Fyodorov</td><td>Keratoplastika, koʻz mikroxirurgiyasi, sunʼiy gavhar</td></tr></tbody></table></div></section><section class=\"lec-sec\" id=\"lec-3\"><h2>3. Koʻruv organi anatomiyasi</h2><p>Koʻruv organi (organum visus) koʻruv analizatorining periferik qismi hisoblanadi. I. P. Pavlov taʼlimotiga koʻra, har bir analizator uch qismdan iborat. Koʻruv analizatori tarkibiga quyidagilar kiradi:</p><ul><li>periferik (qabul qiluvchi) qism – koʻz olmasi va uning toʻr pardasidagi yorugʻlik sezuvchi hujayralar;</li><li>oʻtkazuvchi yoʻllar – koʻruv nervi, koʻruv nervlarining kesishmasi (xiazma), koʻruv yoʻllari (traktlar), tashqi tizzasimon tanalar va koʻruv nurlanishi;</li><li>markaziy (poʻstloq) qism – bosh miya katta yarim sharlarining ensa boʻlagidagi shporasimon egat atrofida joylashgan koʻrish markazi.</li></ul><p>Koʻrish aʼzosi anatomik jihatdan koʻz olmasi (bulbus oculi) va koʻzning yordamchi apparatidan iborat. Yordamchi apparatga koʻz kosasi (orbita), qovoqlar, konʼyunktiva, koʻz yoshi aʼzolari va koʻz olmasini harakatlantiruvchi muskullar kiradi.</p><figure><img src=\"mavzular/n1/didaktik/03_koruv_yoli.png\" alt=\"1-rasm. Koʻruv analizatorining tuzilishi\" loading=\"lazy\" data-zoom><figcaption>1-rasm. Koʻruv analizatorining tuzilishi</figcaption></figure><h3>Koʻz olmasi</h3><p>Koʻz olmasi sharsimon shaklga ega boʻlib, koʻz kosasining old qismida joylashgan. Katta yoshli odamda uning old-orqa oʻlchami (oʻqi) oʻrtacha 24 mm, koʻndalang oʻlchami 23,5 mm, vertikal oʻlchami 23 mm, massasi 7–8 g ni tashkil etadi. Yangi tugʻilgan chaqaloqda koʻz oʻqi taxminan 16–18 mm boʻladi. Koʻz olmasining old qismidagi eng boʻrtib chiqqan nuqtasi old qutb, orqa qismidagisi esa orqa qutb deb ataladi. Koʻz olmasi devori uchta pardadan – tashqi (fibroz), oʻrta (tomirli) va ichki (toʻr) pardalardan tuzilgan, uning ichi esa nur oʻtkazuvchi tiniq muhitlar bilan toʻlgan.</p><h3>Tashqi – fibroz parda</h3><p>Fibroz parda zich biriktiruvchi toʻqimadan iborat boʻlib, koʻzga shakl beradi va ichki tuzilmalarni himoya qiladi. U ikki qismdan – oldingi tiniq shox parda va orqadagi noshaffof oqsil pardadan tashkil topgan.</p><figure><img src=\"mavzular/n1/didaktik/01_koz_kesimi_belgili.png\" alt=\"2-rasm. Koʻz olmasining gorizontal kesimi\" loading=\"lazy\" data-zoom><figcaption>2-rasm. Koʻz olmasining gorizontal kesimi</figcaption></figure><p>Shox parda (cornea) fibroz pardaning 1/6 qismini egallaydi. U tiniq, yaltiroq, silliq, sferik va oʻta sezgir. Katta yoshdagi odamda shox pardaning gorizontal diametri 11–12 mm, yangi tugʻilgan chaqaloqda esa 9–10 mm atrofida boʻladi. Qalinligi markazida 0,5–0,6 mm, chekkasida 1 mm gacha. Shox parda besh qavatdan iborat: oldingi epiteliy, Boumen membranasi, xususiy modda (stroma), Descemet membranasi va orqa epiteliy (endoteliy). Shox pardada qon tomirlari boʻlmaydi, lekin u uch shoxli nervning tolalariga juda boy, shuning uchun uning yuzasiga eng kichik yot jism tushsa ham kuchli ogʻriq, koʻz yoshlanishi va qovoqlarning qisilishi (himoya refleksi) yuzaga keladi. Shox parda koʻz ichi suyuqligi, koʻz yoshi pardasi va limb atrofidagi qon tomirlar toʻri hisobiga oziqlanadi. Uning asosiy vazifasi – nurni oʻtkazish va sindirish (sindirish kuchi 40–43 dioptriya).</p><p>Oqsil parda (sclera) fibroz pardaning 5/6 qismini tashkil etadi. U oq rangli, noshaffof, zich kollagen tolalardan iborat, qalinligi 0,3–1 mm. Bolalarda sklera yupqa boʻlgani uchun koʻkimtir tusda, keksalarda esa sargʻishroq koʻrinadi. Orqa qutbda sklera gʻalvirsimon plastinkani hosil qiladi, uning teshiklaridan koʻruv nervi tolalari chiqib ketadi. Skleraga koʻzni harakatlantiruvchi muskullar birikadi. Shox pardaning skleraga oʻtish joyi limb deb ataladi (kengligi taxminan 1 mm). Sklera koʻzga shakl beradi va ichki pardalarni himoya qiladi.</p><h3>Oʻrta – tomirli parda</h3><p>Tomirli parda qon tomirlariga boy boʻlib, koʻzning ichki tuzilmalarini oziqlantiradi. U uch qismdan iborat: rangdor parda, kiprikli (kipriksimon) tana va xususiy tomirli parda.</p><p>Rangdor parda (iris) tomirli pardaning oldingi qismi boʻlib, shox parda orqasida vertikal holatda joylashgan. Uning rangi tarkibidagi pigment miqdoriga bogʻliq (koʻk, kulrang, yashil, jigarrang). Rangdor pardaning markazida yumaloq teshik – qorachiq (pupilla) bor, normada uning diametri 3–4 mm. Rangdor pardada ikki silliq muskul joylashgan: qorachiqni toraytiruvchi muskul (koʻzni harakatlantiruvchi nervning parasimpatik tolalari innervatsiya qiladi) va qorachiqni kengaytiruvchi muskul (simpatik nerv tolalari innervatsiya qiladi). Qorachiq yorugʻlikda torayadi, qorongʻilikda kengayadi, yaʼni u fotoapparatning diafragmasi kabi koʻzga tushadigan yorugʻlik miqdorini boshqaradi.</p><p>Kiprikli tana (corpus ciliare) rangdor parda bilan xususiy tomirli parda oʻrtasida halqa shaklida joylashgan. Uning oʻsimtalari koʻz ichi suyuqligini ishlab chiqaradi. Kiprikli tanadagi muskul Sinn boylamlari orqali gavharga taʼsir etib, uning egriligini oʻzgartiradi va akkomodatsiyani – koʻzning turli masofadagi narsalarni aniq koʻrishga moslashishini taʼminlaydi. Kiprikli tana yalligʻlanganda (iridotsiklit) koʻzni bosib koʻrganda ogʻriq paydo boʻladi.</p><p>Xususiy tomirli parda (chorioidea) tomirli pardaning orqa, eng katta qismi boʻlib, sklera bilan toʻr parda oʻrtasida joylashgan. U asosan qon tomirlardan tuzilgan va toʻr pardaning tashqi qavatlarini, ayniqsa yorugʻlik sezuvchi hujayralarni oziqlantiradi.</p><h3>Ichki – toʻr parda</h3><p>Toʻr parda (retina) koʻz olmasining eng ichki, yupqa, tiniq pardasi boʻlib, yorugʻlik taʼsirini nerv impulsiga aylantiradi. U ikki qismdan iborat: optik (koʻruvchi) qism – toʻr pardaning orqadagi 2/3 qismi, va koʻrmaydigan qism – kiprikli tana va rangdor pardaning orqa yuzasini qoplab turadi. Optik qism mikroskopik jihatdan 10 qavatdan tuzilgan. Uning eng muhim hujayralari – yorugʻlik sezuvchi fotoretseptorlar: tayoqchalar va kolbachalar.</p><ul><li>Tayoqchalar soni taxminan 120–130 million, ular asosan toʻr pardaning periferik qismida joylashgan; kuchsiz yorugʻlikni sezadi va gʻira-shira hamda qorongʻida koʻrishni taʼminlaydi. Tayoqchalarda koʻruv purpuri – rodopsin bor, uning hosil boʻlishi uchun A vitamini zarur.</li><li>Kolbachalar soni taxminan 6–7 million, ular asosan markazda – sariq dogʻda toʻplangan; kunduzgi yorugʻlikda ishlaydi, narsalarning mayda qismlarini va rangini farqlashni taʼminlaydi.</li></ul><p>Koʻz tubida ikki muhim tuzilma koʻrinadi. Sariq dogʻ (macula lutea) – toʻr pardaning markazidagi taxminan 5 mm li soha boʻlib, uning oʻrtasidagi markaziy chuqurcha (fovea) faqat kolbachalardan iborat va eng aniq koʻrish nuqtasi hisoblanadi. Koʻruv nervi diski (soʻrgʻichi) – koʻruv nervi tolalarining koʻz olmasidan chiqish joyi, diametri 1,5–1,8 mm. Bu sohada fotoretseptorlar boʻlmagani uchun u koʻrmaydi va “koʻr dogʻ” (Mariott dogʻi) deb ataladi. Koʻruv nervi diskining markazidan toʻr pardaning markaziy arteriyasi va venasi chiqadi.</p><h3>Koʻzning ichki tiniq muhitlari</h3><p>Koʻz olmasining ichida nur oʻtkazuvchi va nur sindiruvchi tiniq muhitlar joylashgan: koʻz ichi suyuqligi, gavhar va shishasimon tana. Shox parda bilan birgalikda ular koʻzning optik tizimini hosil qiladi.</p><ul><li>Koʻz ichi suyuqligi kiprikli tanada ishlab chiqariladi va koʻzning oldingi kamerasi (shox parda bilan rangdor parda orasidagi boʻshliq, chuqurligi markazda 3–3,5 mm) hamda orqa kamerasini (rangdor parda bilan gavhar orasidagi boʻshliq) toʻldiradi. U shox parda va gavharni oziqlantiradi. Suyuqlik asosan oldingi kamera burchagi va Shlemm kanali orqali vena tizimiga chiqib ketadi. Suyuqlikning ishlab chiqarilishi va chiqib ketishi orasidagi muvozanat koʻz ichi bosimini belgilaydi; uning normasi Maklakov tonometri boʻyicha 18–26 mm sim. ust. Ushbu muvozanat buzilsa, glaukoma rivojlanishi mumkin.</li><li>Gavhar (lens) – ikki tomoni qavariq, tiniq, elastik linza. Diametri 9–10 mm, qalinligi 3,5–5 mm, sindirish kuchi taxminan 18–20 dioptriya. Gavharda qon tomirlari va nervlar yoʻq, u kiprikli tanaga Sinn boylamlari yordamida osilib turadi. Yosh oʻtishi bilan gavhar elastikligini yoʻqotadi (presbiopiya), uning xiralashishi esa katarakta deb ataladi.</li><li>Shishasimon tana (corpus vitreum) – gavhar orqasida joylashgan tiniq, iviqsimon modda; koʻz olmasi hajmining taxminan 2/3 qismini (4 ml ga yaqin) egallaydi, 98–99 foizi suvdan iborat. U koʻzning shaklini saqlaydi va toʻr pardani tomirli pardaga bosib turadi.</li></ul><h3>Koʻzning yordamchi apparati</h3><p>Koʻz kosasi (orbita) – yetti suyakdan (peshona, yonoq, yuqori jagʻ, gʻalvirsimon, ponasimon, koʻz yoshi va tanglay suyaklari) hosil boʻlgan toʻrt qirrali piramida shaklidagi boʻshliq, chuqurligi 4–5 sm. Unda koʻz olmasi, muskullar, nervlar, qon tomirlar va yogʻ toʻqimasi joylashgan. Koʻz kosasi koʻzni tashqi taʼsirlardan himoya qiladi.</p><p>Qovoqlar (palpebrae) – yuqori va pastki teri-muskul burmalari boʻlib, koʻzni yorugʻlik, chang va shikastlardan himoya qiladi, koʻz pirpiratish orqali koʻz yoshini shox parda yuzasiga bir tekis yoyadi. Qovoq terisi juda yupqa va teri osti kletchatkasi boʻsh boʻlgani uchun yalligʻlanishda va jarohatda qovoqlar tez shishadi. Qovoq tarkibida koʻzning aylana muskuli (yuz nervi innervatsiya qiladi), yuqori qovoqni koʻtaruvchi muskul (koʻzni harakatlantiruvchi nerv innervatsiya qiladi), togʻaysimon plastinka va uning ichidagi meybomiy bezlari bor. Qovoqlarning chetida kipriklar oʻsadi, ularning ildizida yogʻ va ter bezlari joylashgan. Qovoqlar orasidagi tirqish koʻz tirqishi deb ataladi.</p><p>Konʼyunktiva (shilliq parda) – qovoqlarning ichki yuzasini va koʻz olmasining old qismini (shox pardagacha) qoplab turuvchi yupqa, tiniq shilliq parda. Uning qovoq konʼyunktivasi, oʻtish burmalari va koʻz olmasi konʼyunktivasi qismlari farqlanadi. Qovoq konʼyunktivasi bilan koʻz olmasi konʼyunktivasi orasidagi yopiq boʻshliq konʼyunktiva boʻshligʻi deyiladi – hamshira tomchi dori va malhamni aynan shu boʻshliqqa, asosan pastki oʻtish burmasiga yuboradi.</p><p>Koʻz yoshi aʼzolari koʻz yoshi ishlab chiqaruvchi va uni oʻtkazuvchi qismlardan iborat. Koʻz yoshi bezi koʻz kosasining yuqori-tashqi burchagida joylashgan. Koʻz yoshi shox parda yuzasini namlab, oziqlantiradi, mikroblardan tozalaydi (tarkibida lizotsim bor) va koʻzning ichki burchagidagi koʻz yoshi koʻlchasiga toʻplanadi. Soʻngra u yuqori va pastki koʻz yoshi nuqtalari, koʻz yoshi naychalari, koʻz yoshi xaltasi va burun-koʻz yoshi kanali orqali burunning pastki yoʻliga oqib tushadi. Bir kecha-kunduzda normada 0,5–1 ml koʻz yoshi ajraladi.</p><p>Koʻz olmasini harakatlantiruvchi muskullar oltita: toʻrtta toʻgʻri (yuqori, pastki, ichki, tashqi) va ikkita qiyshiq (yuqori va pastki) muskul. Ular koʻz olmasini barcha yoʻnalishlarda harakatlantiradi va ikki koʻzning birgalikdagi muvofiq harakatini taʼminlaydi. Yuqori qiyshiq muskulni gʻaltak nervi (IV juft), tashqi toʻgʻri muskulni uzoqlashtiruvchi nerv (VI juft), qolgan muskullarni koʻzni harakatlantiruvchi nerv (III juft) innervatsiya qiladi. Muskullar faoliyati buzilganda gʻilaylik va koʻzda ikkilanib koʻrish paydo boʻladi.</p><p>Koʻz va uning yordamchi apparati asosan ichki uyqu arteriyasining tarmogʻi – koʻz arteriyasi orqali qon bilan taʼminlanadi. Venoz qon koʻz venalari orqali gʻorsimon sinusga quyiladi; yuz venalari bilan bogʻlanishi sababli yuzdagi yiringli jarayonlar (masalan, chipqonni siqish) infeksiyaning miyaga tarqalishiga olib kelishi mumkin. Hamshira buni bemorlarga albatta tushuntirishi lozim.</p><div class=\"tbl\"><table><thead><tr><th>Parda</th><th>Qismlari</th><th>Asosiy vazifasi</th></tr></thead><tbody><tr><td>Tashqi (fibroz)</td><td>Shox parda (1/6), oqsil parda – sklera (5/6)</td><td>Shakl berish, himoya, nur oʻtkazish va sindirish (shox parda)</td></tr><tr><td>Oʻrta (tomirli)</td><td>Rangdor parda, kiprikli tana, xususiy tomirli parda</td><td>Oziqlantirish, yorugʻlik miqdorini boshqarish, koʻz ichi suyuqligi ishlab chiqarish, akkomodatsiya</td></tr><tr><td>Ichki (toʻr)</td><td>Optik qism, koʻrmaydigan qism</td><td>Yorugʻlikni qabul qilish va nerv impulsiga aylantirish</td></tr></tbody></table></div></section><section class=\"lec-sec\" id=\"lec-4\"><h2>4. Koʻruv organining faoliyati (koʻrish funksiyalari)</h2><p>Koʻrish jarayoni quyidagicha amalga oshadi: narsadan qaytgan nurlar shox parda, oldingi kamera suyuqligi, qorachiq, gavhar va shishasimon tanadan oʻtib sinadi va toʻr pardaga, aniqrogʻi sariq dogʻga, kichraytirilgan va teskari tasvir holida tushadi. Fotoretseptorlarda kimyoviy reaksiya natijasida nerv impulsi hosil boʻladi va u koʻruv yoʻllari orqali bosh miya poʻstlogʻining ensa boʻlagiga yetib boradi. Koʻrish markazida tasvir tahlil qilinadi va biz narsani toʻgʻri holatda, rangli va hajmli koʻramiz.</p><p>Koʻzning asosiy koʻrish funksiyalari beshta: markaziy koʻrish, periferik koʻrish, rang koʻrish, yorugʻlik sezish va binokulyar koʻrish. Ularni tekshirishda hamshira faol ishtirok etadi.</p><h3>Markaziy koʻrish (koʻrish oʻtkirligi)</h3><p>Markaziy koʻrish sariq dogʻning markaziy chuqurchasidagi kolbachalar faoliyati bilan bogʻliq boʻlib, narsalarning shakli va mayda qismlarini aniq farqlashni taʼminlaydi. Uning miqdoriy koʻrsatkichi koʻrish oʻtkirligi (visus) deb ataladi – koʻzning ikki nuqtani alohida-alohida koʻra olish qobiliyati. Normal koʻrish oʻtkirligi 1,0 (100 foiz) ga teng.</p><p>Koʻrish oʻtkirligi Sivtsev–Golovin jadvali yordamida 5 metr masofadan tekshiriladi. Jadval 12 qatordan iborat boʻlib, harflar yuqoridan pastga kichrayib boradi; har bir qator yonida koʻrish oʻtkirligi (V) koʻrsatilgan (0,1 dan 2,0 gacha). Maktabgacha yoshdagi bolalarni tekshirish uchun rasmli Orlova jadvali ishlatiladi. Jadval Rot apparatida bir tekis yoritilgan boʻlishi kerak (taxminan 700 lyuks).</p><p>Tekshirish tartibi: bemor jadvaldan 5 m masofada oʻtiradi; har bir koʻz alohida tekshiriladi – avval oʻng (OD), keyin chap (OS) koʻz; tekshirilmayotgan koʻz maxsus toʻsiq (shitok) bilan bosilmasdan yopiladi; hamshira koʻrsatgich bilan harflarni yuqori qatordan boshlab koʻrsatadi, har bir belgini oʻqish uchun 2–3 soniya beriladi. Koʻrish oʻtkirligi bemor xatosiz oʻqiy olgan eng pastki qatorga koʻra aniqlanadi (0,3–0,6 qatorlarda bitta, 0,7–1,0 qatorlarda ikkita xatoga yoʻl qoʻyiladi). Natija tibbiy hujjatga quyidagicha yoziladi: Visus OD = 1,0; Visus OS = 0,8.</p><p>Agar bemor 5 m dan eng yuqori qatorni koʻra olmasa, u jadvalga yaqinlashtiriladi va Snellen formulasi boʻyicha hisoblanadi: V = d / D, bu yerda d – bemor eng yuqori qatorni oʻqigan masofa, D – shu qatorni normal koʻz koʻradigan masofa (50 m). Masalan, bemor birinchi qatorni 2 m dan oʻqisa, V = 2/50 = 0,04. Koʻrish oʻtkirligi 0,005 dan past boʻlsa, yorugʻlik sezishi tekshiriladi. Qorongʻi xonada koʻzga turli tomondan yorugʻlik tushiriladi: bemor yorugʻlikni sezsa va uning yoʻnalishini toʻgʻri aniqlasa – “yorugʻlikni toʻgʻri proyeksiya bilan sezadi” (1/∞ pr. l. certa), notoʻgʻri aniqlasa – “notoʻgʻri proyeksiya bilan” deb yoziladi. Yorugʻlikni umuman sezmasa, koʻrish oʻtkirligi nolga teng (V = 0) – bu mutlaq koʻrlikdir.</p><h3>Periferik koʻrish (koʻruv maydoni)</h3><figure><img src=\"mavzular/n1/didaktik/04_sivtsev_jadvali.png\" alt=\"3-rasm. Sivtsev–Golovin jadvali\" loading=\"lazy\" data-zoom><figcaption>3-rasm. Sivtsev–Golovin jadvali</figcaption></figure><p>Periferik koʻrish toʻr pardaning chekka qismlaridagi asosan tayoqchalar faoliyatiga bogʻliq boʻlib, atrofdagi fazoda moʻljal olish, harakatlanuvchi narsalarni sezish va qorongʻida yoʻl topishni taʼminlaydi. Koʻz bir nuqtaga qimirlamay qaraganda bir vaqtda koʻra oladigan fazo koʻruv maydoni deyiladi. Uni taxminiy (nazorat) usulda – shifokor yoki hamshira oʻz koʻruv maydoni bilan taqqoslab, yoki aniq usulda – perimetr asbobida (perimetriya) tekshiriladi. Oq rang uchun koʻruv maydonining normal chegaralari: tashqi tomonda 90°, pastki tomonda 65°, ichki tomonda 55°, yuqori tomonda 50° atrofida. Koʻruv maydonining torayishi glaukoma, toʻr parda va koʻruv nervi kasalliklarida, uning ichida koʻrmaydigan qismlar (skotomalar) paydo boʻlishi esa toʻr parda va koʻruv yoʻllari zararlanganda kuzatiladi. Koʻruv maydonining yarmi tushib qolishi gemianopsiya deb ataladi va bosh miya kasalliklarida uchraydi.</p><h3>Rang koʻrish</h3><p>Rang koʻrish kolbachalar faoliyati bilan bogʻliq. Yung–Gelmgols uch komponentli nazariyasiga koʻra, toʻr pardada uch xil kolbacha mavjud: qizil, yashil va koʻk ranglarni sezuvchi kolbachalar. Ularning turlicha qoʻzgʻalishi natijasida biz barcha rang va tuslarni koʻramiz. Uch rangni ham normal sezish normal trixromaziya deyiladi. Rang koʻrishning tugʻma buzilishi koʻpincha erkaklarda uchraydi va irsiy yoʻl bilan (X xromosoma orqali) beriladi. Qizil rangni sezmaslik – protanopiya, yashil rangni sezmaslik – deyteranopiya, koʻk rangni sezmaslik – tritanopiya deb ataladi. Qizil va yashil ranglarni farqlay olmaslik ingliz olimi J. Dalton nomi bilan daltonizm deyiladi. Rang koʻrishning orttirilgan buzilishlari toʻr parda va koʻruv nervi kasalliklarida kuzatiladi.</p><p>Rang koʻrish Rabkin polixromatik jadvallari yordamida tekshiriladi. Jadvallarda bir xil yorqinlikdagi, lekin turli rangdagi doirachalardan raqam yoki shakl tuzilgan boʻlib, rang koʻrishi buzilgan odam ularni farqlay olmaydi. Tekshiruv kunduzgi yorugʻlikda, 1 m masofada oʻtkaziladi, har bir jadvalni koʻrish uchun 5–10 soniya beriladi. Rang koʻrishni tekshirish haydovchilar, uchuvchilar, temir yoʻl va dengiz transporti xodimlari, shifokorlar va boshqa bir qator kasb egalarining kasbiy tanlovida majburiydir.</p><figure><img src=\"mavzular/n1/didaktik/05_koruv_maydoni.png\" alt=\"4-rasm. Koʻruv maydonining normal chegaralari\" loading=\"lazy\" data-zoom><figcaption>4-rasm. Koʻruv maydonining normal chegaralari</figcaption></figure><h3>Yorugʻlik sezish va qorongʻilikka moslashish</h3><p>Yorugʻlik sezish – koʻzning yorugʻlikni va uning eng kam miqdorini idrok etish qobiliyati boʻlib, asosan tayoqchalar faoliyatiga bogʻliq. Koʻzning turli yoritilganlik darajasiga moslashishi adaptatsiya deyiladi. Yorugʻ joydan qorongʻi joyga oʻtganda koʻz asta-sekin qorongʻilikka moslashadi (qorongʻilik adaptatsiyasi 40–60 daqiqa davom etadi), aksincha, yorugʻlikka moslashish tez – 1 daqiqa atrofida yuz beradi. Qorongʻilik adaptatsiyasining buzilishi gemeralopiya (xalq orasida “tovuq koʻrlik”) deb ataladi: bemor kunduzi yaxshi koʻradi, gʻira-shira va qorongʻida esa koʻrmaydi. U koʻpincha A vitamini yetishmovchiligida (orttirilgan, funksional gemeralopiya) yoki toʻr parda kasalliklarida (tugʻma, simptomatik gemeralopiya) uchraydi. Funksional gemeralopiyada A vitamini va unga boy mahsulotlar (sabzi, jigar, sariyogʻ, tuxum sarigʻi) tavsiya etiladi.</p><figure><img src=\"mavzular/n1/didaktik/06_rang_plastinka.png\" alt=\"5-rasm. Polixromatik plastinka namunasi (raqam: 74)\" loading=\"lazy\" data-zoom><figcaption>5-rasm. Polixromatik plastinka namunasi (raqam: 74)</figcaption></figure><h3>Binokulyar koʻrish</h3><p>Binokulyar koʻrish – ikki koʻz bilan birgalikda koʻrishda ikkala koʻzdagi tasvirlarning bosh miya poʻstlogʻida yagona tasvirga qoʻshilishi (fuziya). Binokulyar koʻrish narsalarni hajmli (stereoskopik) koʻrish, ularning chuqurligi va masofasini aniq baholash imkonini beradi. U bolalarda 3–6 yoshgacha shakllanadi. Binokulyar koʻrish uchun ikki koʻzning koʻrish oʻtkirligi yetarli va bir-biriga yaqin boʻlishi, koʻz muskullari muvofiq ishlashi kerak. Gʻilaylikda binokulyar koʻrish buziladi. Binokulyar koʻrish oddiy sinamalar bilan tekshiriladi: Sokolov sinamasi (“kaftdagi teshik”), qalamlar bilan sinama (bemor qalam uchini ikkinchi qalam uchiga tekkizishi kerak), shuningdek toʻrt nuqtali rang testi asbobida. Binokulyar koʻrish haydovchi, uchuvchi, jarroh kabi kasblar uchun juda muhim.</p><h3>Koʻrish funksiyalarini tekshirishda hamshiraning vazifalari</h3><ul><li>tekshiruv xonasi va asboblarni (jadvallar, Rot apparati, koʻrsatgich, toʻsiq, Rabkin jadvallari) tayyorlash;</li><li>bemorga tekshiruvning maqsadi va tartibini tushuntirish, uni qulay joylashtirish;</li><li>har bir koʻzni alohida tekshirish, koʻzni bosmasdan yopishni nazorat qilish;</li><li>natijalarni tibbiy hujjatga aniq va toʻgʻri yozish;</li><li>toʻsiq va koʻrsatgichni har bir bemordan keyin dezinfeksiya qilish;</li><li>aholiga koʻrish gigiyenasi (toʻgʻri yoritish, kompyuterda ishlash tartibi, 20–20–20 qoidasi) boʻyicha maslahat berish.</li></ul><p>Xulosa: koʻruv organi murakkab tuzilgan, nozik va oʻta muhim aʼzo. Uning tuzilishi va funksiyalarini chuqur bilish hamshiraga koʻz kasalliklarini erta aniqlash, tekshiruvlarni toʻgʻri oʻtkazish, bemorlarni sifatli parvarish qilish va aholi oʻrtasida profilaktik ishlarni samarali tashkil etish imkonini beradi.</p></section>", "lecture_toc": ["1. “Oftalmologiya” fani haqida tushuncha va uning tibbiyot fanlari orasidagi oʻrni", "2. Oftalmologiya fanining rivojlanish tarixi", "3. Koʻruv organi anatomiyasi", "4. Koʻruv organining faoliyati (koʻrish funksiyalari)"], "tests": [{"q": "“Oftalmologiya” soʻzi qaysi tildan olingan?", "o": ["Yunon tilidan", "Lotin tilidan", "Arab tilidan", "Fors tilidan"], "a": 0}, {"q": "Inson tashqi muhit haqidagi maʼlumotning taxminan qancha qismini koʻrish orqali oladi?", "o": ["80–90 foizini", "30–40 foizini", "50 foizini", "10–20 foizini"], "a": 0}, {"q": "Abu Ali ibn Sino koʻz kasalliklarini “Tib qonunlari”ning qaysi kitobida bayon qilgan?", "o": ["3-kitobida", "1-kitobida", "5-kitobida", "2-kitobida"], "a": 0}, {"q": "Oftalmoskopni kim ixtiro qilgan?", "o": ["G. Gelmgols", "G. Snellen", "J. Daviel", "I. Kepler"], "a": 0}, {"q": "Katarakta ekstraksiyasini birinchi boʻlib bajargan olim:", "o": ["J. Daviel", "A. Gullstrand", "F. Donders", "V. P. Filatov"], "a": 0}, {"q": "Tasvir toʻr pardada hosil boʻlishini kim isbotlagan?", "o": ["I. Kepler", "Galen", "Gippokrat", "G. Snellen"], "a": 0}, {"q": "Koʻruv analizatori qaysi qismlardan iborat?", "o": ["Periferik qism, oʻtkazuvchi yoʻllar, poʻstloq markazi", "Koʻz olmasi, qovoqlar, konʼyunktiva", "Shox parda, gavhar, toʻr parda", "Koʻz kosasi, muskullar, koʻz yoshi bezi"], "a": 0}, {"q": "Koʻrish markazi bosh miyaning qaysi boʻlagida joylashgan?", "o": ["Ensa boʻlagida", "Peshona boʻlagida", "Chakka boʻlagida", "Tepa boʻlagida"], "a": 0}, {"q": "Koʻz olmasi devori qaysi pardalardan iborat?", "o": ["Fibroz, tomirli, toʻr parda", "Fibroz, shilliq, toʻr parda", "Shox, oqsil, shilliq parda", "Tomirli, shilliq, muskul qavat"], "a": 0}, {"q": "Fibroz parda qaysi qismlardan tashkil topgan?", "o": ["Shox parda va sklera", "Shox parda va rangdor parda", "Sklera va konʼyunktiva", "Rangdor parda va kiprikli tana"], "a": 0}, {"q": "Katta yoshli odamda shox pardaning gorizontal diametri:", "o": ["11–12 mm", "8 mm", "15 mm", "20 mm"], "a": 0}, {"q": "Shox parda qanday oziqlanadi?", "o": ["Koʻz ichi suyuqligi, koʻz yoshi va limb tomirlari hisobiga", "Faqat oʻz qon tomirlari orqali", "Shishasimon tana orqali", "Koʻruv nervi orqali"], "a": 0}, {"q": "Qon tomirlari yoʻq, lekin nerv tolalariga juda boy parda:", "o": ["Shox parda", "Sklera", "Xususiy tomirli parda", "Kiprikli tana"], "a": 0}, {"q": "Skleraning asosiy vazifasi:", "o": ["Koʻzga shakl berish va himoya qilish", "Nurni sindirish", "Akkomodatsiya", "Koʻz ichi suyuqligini ishlab chiqarish"], "a": 0}, {"q": "Tomirli parda qanday qismlardan iborat?", "o": ["Rangdor parda, kiprikli tana, xususiy tomirli parda", "Shox parda, sklera, limb", "Gavhar, shishasimon tana", "Sariq dogʻ, koʻruv nervi diski"], "a": 0}, {"q": "Qorachiq koʻzning qaysi qismida joylashgan?", "o": ["Rangdor pardada", "Shox pardada", "Gavharda", "Toʻr pardada"], "a": 0}, {"q": "Qorachiqni toraytiruvchi muskulni qaysi nerv tolalari innervatsiya qiladi?", "o": ["Koʻzni harakatlantiruvchi nervning parasimpatik tolalari", "Simpatik nerv tolalari", "Yuz nervi", "Uch shoxli nerv"], "a": 0}, {"q": "Koʻz ichi suyuqligi qayerda ishlab chiqariladi?", "o": ["Kiprikli tanada", "Koʻz yoshi bezida", "Gavharda", "Shishasimon tanada"], "a": 0}, {"q": "Akkomodatsiyani taʼminlaydigan tuzilma:", "o": ["Kiprikli tana muskuli va gavhar", "Sklera", "Koʻruv nervi", "Konʼyunktiva"], "a": 0}, {"q": "Kunduzgi va rangli koʻrishni taʼminlovchi hujayralar:", "o": ["Kolbachalar", "Tayoqchalar", "Ganglioz hujayralar", "Pigment epiteliy"], "a": 0}, {"q": "Tayoqchalardagi koʻruv purpuri (rodopsin) hosil boʻlishi uchun qaysi vitamin zarur?", "o": ["A vitamini", "C vitamini", "D vitamini", "B12 vitamini"], "a": 0}, {"q": "Toʻr pardaning eng aniq koʻrish nuqtasi:", "o": ["Sariq dogʻning markaziy chuqurchasi", "Koʻruv nervi diski", "Toʻr pardaning periferiyasi", "Tishsimon chiziq"], "a": 0}, {"q": "“Koʻr dogʻ” (Mariott dogʻi) qayerda joylashgan?", "o": ["Koʻruv nervi diskida", "Sariq dogʻda", "Shox pardada", "Gavharda"], "a": 0}, {"q": "Koʻzning ichki tiniq muhitlari:", "o": ["Koʻz ichi suyuqligi, gavhar, shishasimon tana", "Shox parda, sklera, gavhar", "Rangdor parda, gavhar, qorachiq", "Konʼyunktiva, koʻz yoshi, gavhar"], "a": 0}, {"q": "Maklakov tonometri boʻyicha koʻz ichi bosimining normasi:", "o": ["18–26 mm sim. ust.", "5–10 mm sim. ust.", "30–40 mm sim. ust.", "120/80 mm sim. ust."], "a": 0}, {"q": "Gavharning sindirish kuchi taxminan:", "o": ["18–20 dioptriya", "40–43 dioptriya", "5 dioptriya", "60 dioptriya"], "a": 0}, {"q": "Koʻz yoshi bezi qayerda joylashgan?", "o": ["Koʻz kosasining yuqori-tashqi burchagida", "Koʻzning ichki burchagida", "Pastki qovoqda", "Burun boʻshligʻida"], "a": 0}, {"q": "Koʻz olmasini harakatlantiruvchi muskullar soni:", "o": ["6 ta", "4 ta", "8 ta", "5 ta"], "a": 0}, {"q": "Tashqi toʻgʻri muskulni qaysi nerv innervatsiya qiladi?", "o": ["Uzoqlashtiruvchi nerv (VI juft)", "Gʻaltak nervi (IV juft)", "Koʻzni harakatlantiruvchi nerv (III juft)", "Yuz nervi (VII juft)"], "a": 0}, {"q": "Koʻrish oʻtkirligi Sivtsev–Golovin jadvali bilan qanday masofadan tekshiriladi?", "o": ["5 m", "1 m", "3 m", "10 m"], "a": 0}, {"q": "Bemor jadvalning birinchi qatorini 1 m dan oʻqidi. Koʻrish oʻtkirligi:", "o": ["0,02", "0,1", "0,2", "0,01"], "a": 0}, {"q": "Oq rang uchun koʻruv maydonining tashqi chegarasi normada:", "o": ["90°", "50°", "30°", "120°"], "a": 0}, {"q": "Rang koʻrish qaysi jadvallar yordamida tekshiriladi?", "o": ["Rabkin polixromatik jadvallari", "Sivtsev–Golovin jadvali", "Orlova jadvali", "Snellen jadvali"], "a": 0}, {"q": "Qizil rangni sezmaslik qanday ataladi?", "o": ["Protanopiya", "Deyteranopiya", "Tritanopiya", "Gemianopsiya"], "a": 0}, {"q": "Gemeralopiya (“tovuq koʻrlik”) – bu:", "o": ["Qorongʻilik adaptatsiyasining buzilishi", "Rang koʻrishning buzilishi", "Koʻruv maydonining yarmi tushib qolishi", "Ikkilanib koʻrish"], "a": 0}, {"q": "Binokulyar koʻrishni tekshirish usuli:", "o": ["Sokolov sinamasi (“kaftdagi teshik”)", "Tonometriya", "Perimetriya", "Rabkin jadvallari"], "a": 0}], "gallery": [{"f": "plakat.jpg", "t": "Mavzu boʻyicha infografika-plakat", "d": "Mavzuning asosiy savollarini yorituvchi koʻrgazmali plakat (muallif ishlanmasi)."}, {"f": "01_koz_kesimi_belgili.png", "t": "Koʻz olmasining kesimi (belgilangan)", "d": "Pardalar, ichki muhitlar, koʻruv nervi va muskullar."}, {"f": "02_koz_kesimi_raqamli.png", "t": "Koʻz olmasining kesimi (topshiriq uchun)", "d": "1–16 raqamli tuzilmalarni nomlang."}, {"f": "03_koruv_yoli.png", "t": "Koʻruv analizatori", "d": "Periferik qism, oʻtkazuvchi yoʻllar va poʻstloq markazi."}, {"f": "08_klaster_koruv_organi.png", "t": "Klaster: koʻruv organi", "d": "Koʻz olmasi va yordamchi apparat tuzilmalari."}, {"f": "07_tarix_vaqt_chizigi.png", "t": "Oftalmologiya tarixi", "d": "Qadimgi davrdan XX asrgacha asosiy kashfiyotlar."}, {"f": "04_sivtsev_jadvali.png", "t": "Sivtsev–Golovin jadvali", "d": "Koʻrish oʻtkirligini aniqlash jadvali namunasi."}, {"f": "05_koruv_maydoni.png", "t": "Koʻruv maydoni chegaralari", "d": "Oʻng koʻz uchun oq rangda normal chegaralar."}, {"f": "06_rang_plastinka.png", "t": "Polixromatik plastinka", "d": "Rang koʻrishni tekshirish namunasi (norma: 74)."}, {"f": "umumiy_plakat.jpg", "t": "Oftalmologiya: umumiy plakat", "d": "Fan haqida umumiy koʻrgazmali plakat (muallif ishlanmasi)."}], "glossary": [{"t": "Adaptatsiya", "l": "adaptatio", "d": "Koʻzning turli yoritilganlik darajasiga moslashishi (qorongʻilik va yorugʻlik adaptatsiyasi)."}, {"t": "Akkomodatsiya", "l": "accommodatio", "d": "Koʻzning gavhar egriligini oʻzgartirib, turli masofadagi narsalarni aniq koʻrishga moslashishi."}, {"t": "Analizator", "l": "analysator", "d": "Taʼsirlarni qabul qiluvchi, oʻtkazuvchi va tahlil qiluvchi qismlardan iborat nerv tizimi; koʻruv analizatori."}, {"t": "Binokulyar koʻrish", "l": "visus binocularis", "d": "Ikki koʻz bilan birgalikda koʻrib, narsani yagona, hajmli tasvir sifatida idrok etish."}, {"t": "Daltonizm", "l": "daltonismus", "d": "Qizil va yashil ranglarni farqlay olmaslik; rang koʻrishning tugʻma buzilishi."}, {"t": "Deyteranopiya", "l": "deuteranopia", "d": "Yashil rangni sezmaslik."}, {"t": "Dioptriya", "l": "dioptria", "d": "Linza yoki optik tizimning sindirish kuchi birligi (D); fokus masofasi 1 m boʻlgan linza kuchi."}, {"t": "Fotoretseptorlar", "l": "photoreceptores", "d": "Toʻr pardaning yorugʻlik sezuvchi hujayralari – tayoqchalar va kolbachalar."}, {"t": "Fuziya", "l": "fusio", "d": "Ikki koʻzdagi tasvirlarning bosh miya poʻstlogʻida yagona tasvirga qoʻshilishi."}, {"t": "Gavhar", "l": "lens", "d": "Rangdor parda va shishasimon tana orasidagi ikki tomoni qavariq, tiniq, elastik linza."}, {"t": "Gemeralopiya", "l": "hemeralopia", "d": "Qorongʻilik adaptatsiyasining buzilishi, gʻira-shira va qorongʻida yomon koʻrish (“tovuq koʻrlik”)."}, {"t": "Gemianopsiya", "l": "hemianopsia", "d": "Koʻruv maydonining yarmi tushib qolishi."}, {"t": "Iris", "l": "iris", "d": "Rangdor parda – tomirli pardaning oldingi qismi, markazida qorachiq joylashgan."}, {"t": "Kiprikli tana", "l": "corpus ciliare", "d": "Tomirli pardaning oʻrta qismi; koʻz ichi suyuqligini ishlab chiqaradi, akkomodatsiyada qatnashadi."}, {"t": "Kolbachalar", "l": "coni", "d": "Kunduzgi va rangli koʻrishni taʼminlovchi fotoretseptorlar; sariq dogʻda koʻp."}, {"t": "Konʼyunktiva", "l": "conjunctiva", "d": "Qovoqlarning ichki yuzasini va koʻz olmasining old qismini qoplovchi shilliq parda."}, {"t": "Koʻruv maydoni", "l": "campus visus", "d": "Koʻz bir nuqtaga qimirlamay qaraganda bir vaqtda koʻra oladigan fazo."}, {"t": "Koʻruv nervi diski", "l": "discus nervi optici", "d": "Koʻruv nervi tolalarining koʻz olmasidan chiqish joyi; “koʻr dogʻ”."}, {"t": "Koʻz ichi bosimi", "l": "tensio intraocularis", "d": "Koʻz ichidagi suyuqlik bosimi; Maklakov boʻyicha normasi 18–26 mm sim. ust."}, {"t": "Limb", "l": "limbus corneae", "d": "Shox pardaning skleraga oʻtish joyi, kengligi taxminan 1 mm."}, {"t": "Makula", "l": "macula lutea", "d": "Sariq dogʻ – toʻr pardaning eng aniq koʻrish sohasi."}, {"t": "Oftalmologiya", "l": "ophthalmologia", "d": "Koʻruv aʼzosining tuzilishi, faoliyati va kasalliklarini oʻrganuvchi tibbiyot fani."}, {"t": "Oftalmoskopiya", "l": "ophthalmoscopia", "d": "Koʻz tubini maxsus asbob – oftalmoskop yordamida tekshirish."}, {"t": "Orbita", "l": "orbita", "d": "Koʻz kosasi – yetti suyakdan hosil boʻlgan, koʻz olmasi joylashgan boʻshliq."}, {"t": "Perimetriya", "l": "perimetria", "d": "Koʻruv maydonini perimetr asbobi yordamida tekshirish."}, {"t": "Presbiopiya", "l": "presbyopia", "d": "Yoshga bogʻliq akkomodatsiyaning susayishi, yaqindan koʻrishning qiyinlashishi."}, {"t": "Protanopiya", "l": "protanopia", "d": "Qizil rangni sezmaslik."}, {"t": "Qorachiq", "l": "pupilla", "d": "Rangdor parda markazidagi yumaloq teshik, koʻzga tushadigan yorugʻlik miqdorini boshqaradi."}, {"t": "Refraksiya", "l": "refractio", "d": "Koʻzning optik tizimida nurlarning sinishi."}, {"t": "Retina", "l": "retina", "d": "Toʻr parda – yorugʻlikni qabul qilib, nerv impulsiga aylantiruvchi ichki parda."}, {"t": "Rodopsin", "l": "rhodopsinum", "d": "Tayoqchalardagi koʻruv purpuri; hosil boʻlishi uchun A vitamini zarur."}, {"t": "Sklera", "l": "sclera", "d": "Oqsil parda – fibroz pardaning oq, noshaffof qismi."}, {"t": "Skotoma", "l": "scotoma", "d": "Koʻruv maydoni ichidagi koʻrmaydigan soha."}, {"t": "Tayoqchalar", "l": "bacilli", "d": "Gʻira-shira va qorongʻida koʻrishni taʼminlovchi fotoretseptorlar."}, {"t": "Tonometriya", "l": "tonometria", "d": "Koʻz ichi bosimini oʻlchash."}, {"t": "Tritanopiya", "l": "tritanopia", "d": "Koʻk rangni sezmaslik."}, {"t": "Trixromaziya", "l": "trichromasia", "d": "Uch asosiy rangni (qizil, yashil, koʻk) normal sezish."}, {"t": "Visus", "l": "visus", "d": "Koʻrish oʻtkirligi – koʻzning ikki nuqtani alohida koʻra olish qobiliyati; normasi 1,0."}, {"t": "Xiazma", "l": "chiasma opticum", "d": "Koʻruv nervlarining qisman kesishgan joyi."}, {"t": "Xorioideya", "l": "chorioidea", "d": "Xususiy tomirli parda – toʻr pardaning tashqi qavatlarini oziqlantiradi."}, {"t": "Shishasimon tana", "l": "corpus vitreum", "d": "Gavhar orqasidagi tiniq iviqsimon modda, koʻz hajmining 2/3 qismini egallaydi."}, {"t": "Shox parda", "l": "cornea", "d": "Fibroz pardaning oldingi tiniq qismi; nurni oʻtkazadi va sindiradi."}], "slides": [{"title": "Oftalmologiyaning rivojlanish tarixi. Koʻruv organi anatomiyasi. Koʻzning koʻrish faoliyati", "note": "Assalomu alaykum, aziz oʻquvchilar! Bugun “Oftalmologiyada hamshiralik ishi” modulining birinchi mavzusi – oftalmologiyaning rivojlanish tarixi, koʻruv organi anatomiyasi va koʻzning koʻrish faoliyati bilan tanishamiz."}, {"title": "Mashgʻulot rejasi va oʻqitish natijalari", "note": "Mashgʻulot toʻrt savoldan iborat: oftalmologiya fani va uning tibbiyotdagi oʻrni, fanning rivojlanish tarixi, koʻruv organining anatomiyasi va koʻzning koʻrish funksiyalari. Dars yakunida siz koʻzning tuzilishini va beshta asosiy koʻrish funksiyasini aytib bera olasiz."}, {"title": "Oftalmologiya nima?", "note": "Oftalmologiya soʻzi yunoncha “oftalmos” – koʻz va “logos” – taʼlimot soʻzlaridan olingan. Bu fan koʻruv aʼzosining tuzilishi, faoliyati va kasalliklarini oʻrganadi. Inson tashqi muhit haqidagi maʼlumotlarning sakson–toʻqson foizini koʻzi orqali oladi. Jahon sogʻliqni saqlash tashkilotiga koʻra, dunyoda ikki milliard ikki yuz million kishida koʻrish buzilishi mavjud, ularning deyarli yarmida bu holatning oldini olish mumkin edi."}, {"title": "Oftalmologiyaning boshqa fanlar bilan bogʻliqligi", "note": "Koʻplab umumiy kasalliklar koʻzda oʻz aksini topadi. Gipertoniyada koʻz tubi tomirlari torayadi, qandli diabetda diabetik retinopatiya va katarakta rivojlanadi. Shuning uchun oftalmolog terapevt, nevropatolog va endokrinolog bilan hamkorlikda ishlaydi."}, {"title": "Oftalmologiyada hamshiraning vazifalari", "note": "Hamshira bemorni qabul qiladi va tekshiruvga tayyorlaydi, koʻrish oʻtkirligini aniqlashda ishtirok etadi, tomchi dori tomizadi, malham qoʻyadi va koʻzni yuvadi. Shikastlarda birinchi yordam koʻrsatadi. Koʻz infeksiyalari oson yuqgani uchun aseptika qoidalariga qatʼiy rioya qilish shart."}, {"title": "Oftalmologiya tarixi: asosiy bosqichlar", "note": "Koʻz kasalliklari haqidagi dastlabki maʼlumotlar qadimgi Misrning Ebers papirusida uchraydi. Hindistonlik tabib Sushruta katarakta operatsiyasini bajargan. Toʻqqizinchi asrda Hunayn ibn Ishoq “Koʻz haqida oʻn maqola” darsligini yozgan. Yangi davrda Kepler tasvir toʻr pardada hosil boʻlishini isbotlagan, Daviel kataraktani chiqarib olgan, Gelmgols oftalmoskopni, Snellen esa koʻrish jadvalini yaratgan."}, {"title": "Abu Ali ibn Sino va Sharq tabobati", "note": "Buyuk vatandoshimiz Abu Ali ibn Sino “Tib qonunlari” asarining uchinchi kitobida koʻz anatomiyasi va kasalliklarini batafsil bayon qilgan. U koʻzning olti tashqi muskulini, koʻruv nervi kesishmasini tasvirlagan, traxoma, katarakta va tungi koʻrlik haqida yozgan. Uning asarlari bir necha asr davomida Yevropa universitetlarida darslik boʻlgan."}, {"title": "XX asr va hozirgi zamon", "note": "Yigirmanchi asrda Filatov shox pardani koʻchirib oʻtkazish usulini, Fyodorov esa koʻz mikroxirurgiyasi va sunʼiy gavhar qoʻyishni rivojlantirdi. Oʻzbekistonda traxoma ommaviy kasallik sifatida tugatildi, bugun esa kataraktani fakoemulsifikatsiya usulida olib tashlash va lazer operatsiyalari muvaffaqiyatli bajarilmoqda."}, {"title": "Koʻruv analizatori", "note": "Koʻruv analizatori uch qismdan iborat. Periferik qism – koʻz olmasi va toʻr parda. Oʻtkazuvchi yoʻllar – koʻruv nervi, koʻruv nervlari kesishmasi – xiazma, koʻruv yoʻllari va tashqi tizzasimon tanalar. Markaziy qism – bosh miyaning ensa boʻlagidagi koʻrish markazi."}, {"title": "Koʻz olmasining tuzilishi", "note": "Koʻz olmasi sharsimon, uning old-orqa oʻqi oʻrtacha yigirma toʻrt millimetr. Devori uch pardadan iborat: tashqi fibroz parda – shox parda va sklera; oʻrta tomirli parda – rangdor parda, kiprikli tana va xususiy tomirli parda; ichki – toʻr parda. Ichida esa koʻz ichi suyuqligi, gavhar va shishasimon tana joylashgan."}, {"title": "Tashqi – fibroz parda", "note": "Shox parda fibroz pardaning oltidan bir qismini egallaydi. U tiniq, qon tomirlari yoʻq, lekin nerv tolalariga juda boy, shuning uchun unga tushgan kichik yot jism ham kuchli ogʻriq beradi. Sindirish kuchi qirq–qirq uch dioptriya. Sklera esa oq, zich parda boʻlib, koʻzga shakl beradi va uni himoya qiladi."}, {"title": "Oʻrta – tomirli parda", "note": "Tomirli parda uch qismdan iborat. Rangdor parda koʻzga rang beradi, uning markazidagi qorachiq fotoapparat diafragmasi kabi koʻzga tushadigan yorugʻlikni boshqaradi. Kiprikli tana koʻz ichi suyuqligini ishlab chiqaradi va akkomodatsiyani taʼminlaydi. Xususiy tomirli parda toʻr pardani oziqlantiradi."}, {"title": "Ichki – toʻr parda", "note": "Toʻr parda yorugʻlikni nerv impulsiga aylantiradi. Unda ikki xil fotoretseptor bor: tayoqchalar qorongʻida koʻrishni, kolbachalar esa kunduzgi va rangli koʻrishni taʼminlaydi. Eng aniq koʻrish nuqtasi – sariq dogʻ. Koʻruv nervi diskida fotoretseptorlar yoʻq, shuning uchun u koʻr dogʻ deb ataladi."}, {"title": "Ichki tiniq muhitlar va yordamchi apparat", "note": "Koʻzning ichki tiniq muhitlari – koʻz ichi suyuqligi, gavhar va shishasimon tana. Koʻz ichi bosimining normasi Maklakov boʻyicha oʻn sakkiz–yigirma olti millimetr simob ustuni. Yordamchi apparatga koʻz kosasi, qovoqlar, konʼyunktiva, koʻz yoshi aʼzolari va oltita harakatlantiruvchi muskul kiradi."}, {"title": "Koʻzning 5 ta koʻrish funksiyasi", "note": "Koʻzning beshta asosiy koʻrish funksiyasi bor: markaziy koʻrish, periferik koʻrish, rang koʻrish, yorugʻlik sezish va binokulyar koʻrish. Endi ularni qanday tekshirishni koʻrib chiqamiz."}, {"title": "Koʻrish oʻtkirligini tekshirish", "note": "Koʻrish oʻtkirligi Sivtsev–Golovin jadvali bilan besh metr masofadan tekshiriladi. Har bir koʻz alohida tekshiriladi, ikkinchi koʻz toʻsiq bilan bosilmasdan yopiladi. Normal koʻrish oʻtkirligi birga teng. Agar bemor birinchi qatorni ham koʻrmasa, Snellen formulasi qoʻllaniladi: koʻrish oʻtkirligi bemor oʻqigan masofani ellikka boʻlganiga teng."}, {"title": "Koʻruv maydoni va rang koʻrish", "note": "Koʻruv maydoni perimetr asbobida tekshiriladi. Oq rang uchun tashqi chegara toʻqson daraja, ichki chegara ellik besh daraja. Rang koʻrish esa Rabkin polixromatik jadvallari bilan tekshiriladi. Qizil rangni sezmaslik protanopiya, yashilni sezmaslik deyteranopiya deb ataladi."}, {"title": "Yorugʻlik sezish va binokulyar koʻrish", "note": "Koʻz qorongʻilikka qirq–oltmish daqiqada moslashadi. Bu jarayon buzilsa, gemeralopiya – tovuq koʻrlik yuzaga keladi; uning koʻp uchraydigan sababi A vitamini yetishmovchiligidir. Binokulyar koʻrish ikki koʻzdagi tasvirlarning yagona tasvirga qoʻshilishi boʻlib, Sokolov sinamasi bilan tekshiriladi."}, {"title": "Xulosa", "note": "Xulosa qilib aytganda, oftalmologiya ijtimoiy ahamiyati juda yuqori fan. Koʻz olmasi uch parda va uch tiniq muhitdan iborat, koʻzning beshta koʻrish funksiyasi mavjud. Hamshira koʻz kasalliklarini erta aniqlash va profilaktikada muhim oʻrin tutadi. Eʼtiboringiz uchun rahmat! Endi nazorat savollari va testlarga oʻting."}], "video_len": "7:34"};
